mkdir -p /tmp/cpufeed-check && cat > /tmp/cpufeed-check/check.mts <<'EOF'
// Verifies the feed contract the chart relies on. Runs against the real source file.
import {cpuFeed, CPU_STEP_MS} from '/home/sandbox/workspace/src/monitoring/cpuFeed.ts';

const WINDOW = 24 * 60 * 60 * 1000 / CPU_STEP_MS;
const assert = (cond: boolean, msg: string) => { if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; } else console.log('ok  :', msg); };

// 1. Snapshot: exact window size, contiguous, step-aligned, values in range.
const snap = cpuFeed.snapshot();
assert(snap.timestamps.length === WINDOW, `snapshot has ${WINDOW} samples (got ${snap.timestamps.length})`);
let contiguous = true;
for (let i = 1; i < snap.timestamps.length; i++) if (snap.timestamps[i] - snap.timestamps[i-1] !== CPU_STEP_MS) { contiguous = false; break; }
assert(contiguous, 'timestamps contiguous at the step');
assert(snap.values.every(v => v >= 0 && v <= 100), 'values within [0, 100]');
assert(snap.timestamps[snap.timestamps.length-1] % CPU_STEP_MS === 0, 'last timestamp aligned to step');

// 2. Subscriber mirrors Yagr incremental semantics: push batch, then splice(0, batchLen) from the front.
// Feed must never emit an empty batch.
const mirrorTs = snap.timestamps.slice(), mirrorVal = snap.values.slice();
let emptyBatch = false, batches = 0, sawTick = false;
const lastTs = snap.timestamps[snap.timestamps.length - 1];
const unsub = cpuFeed.subscribe(lastTs, (b) => {
  batches++;
  if (b.timestamps.length === 0) emptyBatch = true;
  mirrorTs.push(...b.timestamps); mirrorVal.push(...b.values);
  mirrorTs.splice(0, b.timestamps.length); mirrorVal.splice(0, b.values.length);
  if (b.timestamps.length) sawTick = true;
});
assert(batches === 0 || !emptyBatch, 'no empty batch delivered');

// 3. Wait for a couple of ticks, then check that mirror == feed window (the same data the chart shows).
await new Promise(r => setTimeout(r, CPU_STEP_MS * 2 + 300));
unsub();
const after = cpuFeed.snapshot();
assert(after.timestamps.length === WINDOW, 'window still exactly WINDOW after ticks');
assert(mirrorTs.length === after.timestamps.length && mirrorTs.every((t, i) => t === after.timestamps[i]), 'incremental mirror timestamps equal feed window');
assert(mirrorVal.every((v, i) => v === after.values[i]), 'incremental mirror values equal feed window');
assert(!emptyBatch, 'no empty batch during ticks');
console.log('      batches received:', batches, 'tick seen:', sawTick);

// 4. Catch-up: subscribe with an old sinceTimestamp -> tail is delivered, in order, no duplicates.
const oldSince = after.timestamps[after.timestamps.length - 6]; // 5 samples before the end
let tailCount = 0; let tailTs: number[] = [];
const unsub2 = cpuFeed.subscribe(oldSince, (b) => { tailCount += b.timestamps.length; tailTs = tailTs.concat(b.timestamps); });
unsub2();
assert(tailCount >= 5, `catch-up delivered at least the 5 known newer samples (got ${tailCount})`);
assert(tailTs.every((t, i) => i === 0 || t > tailTs[i-1]), 'catch-up timestamps strictly ascending');
assert(tailTs.every(t => t > oldSince), 'catch-up only contains samples newer than sinceTimestamp');
EOF
cd /tmp/cpufeed-check && node --no-warnings check.mts; echo "exit=$?"

